"""Current saved animation review gallery; no browser navigation."""
from pathlib import Path
import json,html,hashlib
P=Path(__file__).resolve().parent;ROOT=P.parents[2];registry=json.loads((P/'animation-deliveries.json').read_text());matrix=json.loads((P/'enemy-action-matrix.json').read_text());esc=html.escape
parts=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Midnight Menagerie animation review</title><style>body{font:16px/1.5 system-ui;background:#191c26;color:#eee;max-width:1120px;margin:30px auto;padding:20px}a{color:#bcd3ff}video,img{max-width:100%;height:auto}h1,h2{color:#ebd6a5}.notice{padding:18px;border-left:4px solid #b5a0e7;background:#262938}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;border-bottom:1px solid #454956;padding:8px}details{margin:18px 0}pre{white-space:pre-wrap}.clips{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:700px){.clips{grid-template-columns:1fr}}</style><h1>Midnight Menagerie — animation review</h1>']
s=matrix['summary'];parts.append(f'<p class="notice">{s["new_saved_enemies"]} new enemies / {s["new_saved_actions"]} saved provisional actions at 30 fps. <strong>{s["new_final_actions"]} final-approved actions.</strong> {s["pending_actions"]} usable actions remain unproduced; 4 Spectral Scullion actions remain dependency-blocked. The 29 legacy animated enemies / 118 clips are retained unchanged.</p><p>All new poses are staged toward screen-left. Decoded key poses, technical frame checks and authored motion paths have been reviewed; full-speed intended-size visual approval remains pending. Browser navigation was denied and not retried. These local MP4s are independently rendered review deliverables, not in-game tests.</p>')
parts.append('<h2>Current 30 fps review reels</h2><p>Reference figure height: 200 logical pixels using 200 / unit and the recorded pivot. Actual game stage scale varies. Two idle cycles, each one-shot once, and a one-second defeat hold.</p>')
for file in sorted((P/'review-reels').glob('*left*.json')):
 m=json.loads(file.read_text());valid=all(hashlib.sha256((ROOT/i['path']).read_bytes()).hexdigest()==i['sha256'] for i in m['inputs'])
 if not valid:continue
 rel='review-reels/'+file.with_suffix('.mp4').name
 parts.append(f'<h3>{esc(file.stem.replace("-"," "))}</h3><video controls preload="metadata" src="{rel}"></video><p><a href="{rel}">MP4</a> · <a href="review-reels/{file.name}">Decoded video verification</a> — {m["decoded_frames"]} frames / {m["fps"]} fps / {m["duration_seconds"]} s</p>')
parts.append('<h2>Saved enemy actions</h2><p><a href="hall-mirror-preview.html">Hall Mirror frame controls</a> · <a href="batch-02-preview.html">Curtains / Chandelier controls</a> · <a href="batch-03-preview.html">Pots / Shears controls</a> | <a href="batch-04-preview.html">Sheet / Hare controls</a> | <a href="batch-05-preview.html">Bell / Mask controls</a></p>')
for eid,e in registry.items():
 d=P/e['staging'];m=json.loads((d/'index.json').read_text());prod=json.loads((d/'production-manifest.json').read_text())
 parts.append(f'<h3>{esc(eid.replace("-"," ").title())}</h3><p>{esc(prod["method"])}</p><p>{esc(prod["orientation"]["method"])}</p><p><a href="{e["receipt"]}">Saved paths / hashes</a> · <a href="{e["validation"]}">Validation</a> · <a href="{e["staging"]}/orientation-review.json">Direction review and limits</a></p><div class="clips">')
 for state,c in m['clips'].items():
  parts.append(f'<section><h4>{state} — {c["frames"]} frames / {c["frames"]/30:g} s / '+('loop' if c['loop'] else 'hold last' if c['hold'] else 'return')+f'</h4><a href="{e["staging"]}/{state}-contact.jpg"><img src="{e["staging"]}/{state}-contact.jpg" alt="Chronological {eid} {state} poses"></a><p><a href="{e["staging"]}/{state}-preview.webp">Animated WebP</a> · <a href="../../../animations/sprites/enemies/animations/{c["source"]}">PNG sheet</a> · <a href="../../../game/assets/sprites/enemy-clips/{eid}/{c["file"]}">Runtime atlas</a></p></section>')
 parts.append('</div>')
parts.append('<h2>Retained animation direction audit</h2><p><a href="orientation-audit/ORIENTATION-REPORT.txt">Findings and integration constraints</a> · <a href="orientation-audit/orientation-decisions.json">Per-enemy decisions</a> · <a href="orientation-audit/legacy-derivatives/oven-maw/saved-assets.json">Oven Maw left alternate receipt (not integrated)</a></p><p>Slipper Skitter and Blanket Hydra already have runtime reflection. Do not double-flip them. The legacy allowance for frontal faces conflicts with the new screen-left requirement; unresolved cases are recorded individually.</p>')
for i in range(1,7):parts.append(f'<a href="orientation-audit/legacy-runtime-{i}.jpg">Legacy contacts {i}</a> · ')
parts.append('<h2>Full roster/action matrix</h2><p><a href="enemy-action-matrix.json">JSON</a> · <a href="enemy-action-matrix.csv">CSV</a> · <a href="CHECKPOINT.json">Checkpoint</a> · <a href="ANIMATION-PRODUCTION-REPORT.txt">Production report</a> · <a href="preservation-validation.json">Preservation validation</a></p><table><tr><th>Enemy</th><th>Production</th><th>Direction</th><th>Actions</th></tr>')
for e in matrix['entries']:
 status='preserved' if e['existing'] else 'saved provisional' if e['saved'] else 'blocked' if e['base_status']=='blocked' else 'pending'
 parts.append(f'<tr><td>{esc(e["name"])}</td><td>{status}</td><td>{esc(e["actions"][0]["orientation_status"])}</td><td>{", ".join(a["state"] for a in e["actions"])}</td></tr>')
parts.append('</table><details><summary>Historical pre-orientation review</summary><p><a href="review-reels/first-three-enemies-30fps.mp4">Earlier 12-action reel, superseded by the left-staged revisions</a>. Recovered generation and previous stages are retained in the production directory; they are not current final assets.</p></details></html>')
(P/'animation-gallery.html').write_text(''.join(parts),encoding='utf-8');print('Current review gallery saved.')
